void WindowLayout::bringForward( void )
{
	GameWindow *window, *prev;
	int countLeft = m_windowCount;

	for( window = m_windowTail; countLeft; window = prev )
	{

		prev = window->winGetPrevInLayout();
		window->winBringToTop();
		countLeft--;

	}  // end for window

}

