void WindowLayout::addWindow(GameWindow *window)
{
	if (!findWindow(window)) {
		window->winSetPrevInLayout(0);
		window->winSetNextInLayout(m_windowList);
		if (m_windowList)
			m_windowList->winSetPrevInLayout(window);
		m_windowList = window;
		window->winSetLayout(this);
		if (!m_windowTail)
			m_windowTail = window;
		m_windowCount++;
	}
}

// FUNCTION: BFME2 0x00538B95 size=121 name=?removeWindow@WindowLayout@@UAEXPAVGameWindow@@@Z evidence=N:ledger tier=B hypothesis:Z
void WindowLayout::removeWindow(GameWindow *window)
{
	GameWindow *found = findWindow(window);
	if (found) {
		GameWindow *prev = found->winGetPrevInLayout();
		GameWindow *next = found->winGetNextInLayout();
		if (next)
			next->winSetPrevInLayout(prev);
		if (prev)
			prev->winSetNextInLayout(next);
		else
			m_windowList = next;
		found->winSetLayout(0);
		found->winSetNextInLayout(0);
		found->winSetPrevInLayout(0);
		if (m_windowTail == found)
			m_windowTail = prev;
		m_windowCount--;
	}
}

